<script setup lang="ts">
import {ref,onMounted} from 'vue';import {businessApi} from '../stores/business';import type {HomeSummary} from '@shared/mobile';import type {Target} from '@shared/labops-targets.js';import AsyncState from './AsyncState.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
const tasksSection=ref<HTMLElement>(),plansSection=ref<HTMLElement>(),shiftsSection=ref<HTMLElement>();
const emit=defineEmits<{navigate:[Target]}>(),data=ref<HomeSummary>(),loading=ref(true),error=ref('');let generation=0;
async function refresh(){const epoch=++generation;try{const result=await businessApi<HomeSummary>('proxy/mobile-home');if(epoch===generation){data.value=result;error.value='';}}catch(e){if(epoch===generation)error.value=(e as Error).message;}finally{loading.value=false;}}
onMounted(refresh);useVisibleRefresh(refresh);
</script>
<template><AsyncState :loading="loading" :error="error" @retry="refresh"><template v-if="data"><div class="mobile-greeting"><h2>{{data.actor.name}}的工作台</h2><p>{{data.date}} · {{data.actor.identity==='admin'?'管理员':'志愿者'}}</p></div><div class="mobile-counts"><button @click="tasksSection?.scrollIntoView({block:'start'})"><b>{{data.counts.tasks}}</b>本人待办</button><button @click="plansSection?.scrollIntoView({block:'start'})"><b>{{data.counts.pendingPlans}}</b>待确认方案</button><button @click="emit('navigate',{view:'messages'})"><b>{{data.counts.unread}}</b>未读消息</button><button @click="shiftsSection?.scrollIntoView({block:'start'})"><b>{{data.counts.shifts}}</b>今日正式班次</button></div><section ref="tasksSection" class="mobile-section"><h3>今天要做</h3><button v-for="t in data.tasks" :key="t.id" class="mobile-row" @click="emit('navigate',{view:'task',taskId:t.id})"><span>{{t.kind}} · {{t.status}}</span><small>{{t.id}}</small></button><p v-if="!data.tasks.length">本人暂无待办任务。</p><button class="mobile-primary" @click="emit('navigate',{view:'assistant',section:'work'})">新建工作会话</button></section><section ref="plansSection" class="mobile-section"><h3>待本人确认的方案</h3><button v-for="plan in data.pendingPlans" :key="plan.id" class="mobile-row" :disabled="!plan.taskId&&!plan.conversationId" @click="emit('navigate',plan.taskId?{view:'task',taskId:plan.taskId}:{view:'conversation',conversationId:plan.conversationId})"><span>{{plan.kind}}</span><small>{{plan.id}}</small></button><p v-if="!data.pendingPlans.length">当前没有待确认方案。</p></section><section ref="shiftsSection" class="mobile-section"><h3>正式班次与待接收交接</h3><button v-for="s in data.shifts" :key="s.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:s.roomId,action:'duty'})">{{s.date}} · {{s.periodKey}} · {{s.roomId}}</button><button v-for="h in data.handovers" :key="h.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:h.roomId,action:'duty'})">待本人接收 · {{h.id}}</button><p v-if="!data.shifts.length&&!data.handovers.length">暂无今日正式班次和待接收交接。</p></section><section class="mobile-section"><h3>指派给我的工单</h3><button v-for="i in data.issues" :key="i.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:i.roomId,action:'issues'})">{{i.description}} · {{i.status}}</button><p v-if="!data.issues.length">暂无指派给本人的未关闭工单。</p></section><section v-if="data.risk" class="mobile-section"><h3>管理员待核实风险</h3><button v-for="r in data.risk.suspendedRooms" :key="r.roomId" class="mobile-row" @click="emit('navigate',{view:'room',roomId:r.roomId})">{{r.roomName}} · 服务停用</button><button v-for="i in data.risk.unassignedIssues" :key="i.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:i.roomId,action:'issues'})">未指派 · {{i.description}}</button><p v-if="!data.risk.suspendedRooms.length&&!data.risk.unassignedIssues.length">当前登记未发现上述风险，现场情况仍需核实。</p></section><p class="mobile-source">主系统授权查询 · {{data.queriedAt}}<br>版本 {{data.sourceRevision.slice(0,12)}}</p></template></AsyncState></template>
